+            Measurement measurement = measurements.stream()
+                .filter(
+                    m -> m.attributes().get("operation").equals(operation.getKey())
+                        && m.attributes().get("purpose").equals(purpose.getKey())
+                        && m.attributes().get("repo_name").equals(repository)
