+                    ES816BinaryQuantizedVectorsFormat.META_CODEC_NAME,
+                    ES816BinaryQuantizedVectorsFormat.VERSION_START,
+                    ES816BinaryQuantizedVectorsFormat.VERSION_CURRENT,
