+    }
+
+    @Override
+    public IndexInput getSlice() {
+        return slice;
+    }
+
+    @Override
+    public int getVectorByteLength() {
+        return numBytes;
+    }
+
+    public static OffHeapBinarizedVectorValues load(
+        OrdToDocDISIReaderConfiguration configuration,
