+            if ((v[k] & 0b10000000) == 0b10000000) {
+                v1b[m] |= 0b00000001;
+            }
+            if (k % 8 == 7) {
+                m++;
+            } else {
+                v1b[m] <<= 1;
+            }
+        }
+    }
