+            float sqrX = targetDistToC * targetDistToC;
+            double xX0 = targetDistToC / x0;
+
+            // TODO maybe store?
+            float xbSum = (float) BQVectorUtils.popcount(binaryCode);
+            float factorPPC = (float) (-2.0 / sqrtDimensions * xX0 * (xbSum * 2.0 - targetVectors.dimension()));
